9e8d27c7-018b-406c-874b-562f40faba81	02_glass_composition_properties	textbook	en	Coloration in glass is produced by the presence of transition metal ions or rare earth ions in the glass network. Iron (Fe2+/Fe3+) produces blue-green or yellow-brown colors, cobalt (Co2+) produces deep blue, copper (Cu2+) produces blue-green, and chromium (Cr3+) produces green.	{"file_path": "C:\\\\Users\\\\Documents\\\\Projects\\\\glass-expert-ai-phase1\\\\glass-expert-ai\\\\data\\\\sample_docs\\\\02_glass_composition_properties.pdf", "page_count": 3, "chunk_index": 4, "ingested_at": "2026-03-04T13:49:30.192261", "total_chunks": 8}	[-0.02339382,0.0067348843,-0.0011823595,0.034030326,-0.05879793,0.00011653635,-0.006667138,-0.005045149,0.034907352,0.03506339,0.015225989,0.011124311,0.04549741,-0.04880291,0.020682221,-0.03841275,0.007803631,0.023686413,-0.033746965,0.028237425,0.029638259,0.027029308,-0.042869408,0.0034817117,-0.028453017,0.03268321,-0.026322296,0.0011215847,0.059314635,-0.00040828896,-0.04199665,-0.00021004463,0.011319001,-0.049627043,-0.003448449,-0.008729422,0.008402003,-0.01072752,-0.0061862865,-0.06649852,0.08690039,-0.02855494,0.0226336,-0.031519394,-0.042660955,0.008051581,0.0006987391,-0.025804192,-0.031282887,0.003318319,0.033299163,0.025349539,-0.014700279,-0.021233939,-0.03255475,0.031764004,-0.011886973,0.013585149,-0.03303258,-0.013400053,-0.0155736115,0.016967261,0.023917723,-0.04745749,0.0453305,0.049862705,0.007818688,-0.007790176,-0.017971039,-0.014419402,-0.010613531,0.0043778215,0.023283523,-0.023536205,-0.052159302,-0.043083355,-0.016417516,0.0031450032,-0.072326265,-0.0010961489,-0.0130825685,0.046504956,-0.0070417924,0.033752624,-0.00091143226,0.02841632,-0.052902203,0.043550182,0.020419825,-0.013427838,0.004844018,0.05531568,0.0077226716,0.00059991446,-0.004374493,0.011504419,-0.03606056,0.060817182,0.034300584,0.046898466,-0.008160693,0.027540732,-0.030576611,0.022040237,-0.019506516,0.016568111,0.0043591037,0.036478747,-0.046765976,-0.03601325,0.